-- Read-only metadata audit. Not a migration. No user rows.
select jsonb_build_object(
'effective_table_grants',(select jsonb_agg(jsonb_build_object('table',c.relname,'role',r.role,'select',has_table_privilege(r.role,c.oid,'SELECT'),'insert',has_table_privilege(r.role,c.oid,'INSERT'),'update',has_table_privilege(r.role,c.oid,'UPDATE'),'delete',has_table_privilege(r.role,c.oid,'DELETE'),'truncate',has_table_privilege(r.role,c.oid,'TRUNCATE')) order by c.relname,r.role) from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join (values ('anon'),('authenticated')) r(role) where n.nspname='public' and c.relkind in ('r','v','m','p') and c.relname not in ('spatial_ref_sys','geography_columns','geometry_columns')),
'column_acls',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'acl',a.attacl)), '[]'::jsonb) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and a.attnum>0 and not a.attisdropped and a.attacl is not null),
'default_acls',(select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'namespace',n.nspname,'object_type',d.defaclobjtype,'acl',d.defaclacl)) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname='public' or d.defaclnamespace=0),
'views',(select jsonb_agg(jsonb_build_object('name',c.relname,'options',c.reloptions,'definition',pg_get_viewdef(c.oid,true))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='v' and c.relname='index_usage_stats')
) as security;
